// Extract the logo URL from Cloudinary upload response
// If the logo already existed (overwrite:false), Cloudinary still returns the existing secure_url
const res = $input.first().json;
const logoUrl = res.secure_url || 'https://res.cloudinary.com/dmnkmwdmu/image/upload/iksatech/brand/logo.png';
console.log('Logo URL confirmed:', logoUrl);
return [{ json: { logo_url: logoUrl } }];

const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json|```/g, '').trim();
let posts;
try {
  posts = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Failed to parse OpenRouter response: ' + cleaned);
}

const sheetData = $('🔍 Is Row Pending?').first().json;
const draftId = 'draft_' + Date.now();
const serviceName = (sheetData['Service'] || '').replace(/\n|\r/g, ' ').trim();

// Pull the confirmed logo URL from the upstream node
const logoUrl = $('⚙️ Extract Logo URL').first().json.logo_url;

return [{
  json: {
    draft_id:               draftId,
    draft_id_for_button:    draftId,
    Status:                 'Pending',
    service_draft:          serviceName,
    service:                serviceName,
    linkedin_draft:         posts.linkedin,
    instagram_draft:        posts.instagram,
    linkedin:               posts.linkedin,
    instagram:              posts.instagram,
    image_prompt_linkedin:  posts.image_prompt_linkedin,
    image_prompt_instagram: posts.image_prompt_instagram,
    logo_url:               logoUrl
  }
}];

// ─── Build ULTRA PREMIUM HTML Composite for hcti.io ─────────────────────────
// Real IKSATECH logo loaded as <img> from Cloudinary URL
// Glassmorphism card | Metallic gold branding | Neon blue accents
// Matches the reference poster: luxury, futuristic, dark navy

const draft    = $('⚙️ Parse AI Response').first().json;
const liUpload = $('☁️ Upload LinkedIn Image (Cloudinary)').first().json;
const igUpload = $('☁️ Upload Instagram Image (Cloudinary)').first().json;

// Real logo URL from Cloudinary
const logoUrl  = draft.logo_url || 'https://res.cloudinary.com/dmnkmwdmu/image/upload/iksatech/brand/logo.png';

const serviceMap = {
  'Transformation Digitale':                { color: '#00AAFF', accent: '#0055CC', tag: 'TRANSFORMATION DIGITALE' },
  'Marketing Digital & SEO':                { color: '#00CC88', accent: '#007755', tag: 'MARKETING DIGITAL & SEO' },
  'Conception de Visuels & Branding':       { color: '#FF8800', accent: '#CC5500', tag: 'BRANDING & DESIGN' },
  'Solutions IT & Cloud':                   { color: '#00CCFF', accent: '#0088CC', tag: 'CLOUD & IT' },
  'ERP Odoo & Solutions Métier':            { color: '#FFAA00', accent: '#CC7700', tag: 'ERP ODOO' },
  'Développement Web & Mobile':             { color: '#AA44FF', accent: '#6600CC', tag: 'DEV WEB & MOBILE' },
  'Automatisation & RPA':                   { color: '#FF44AA', accent: '#CC0077', tag: 'AUTOMATISATION & RPA' },
  'Intelligence Artificielle':              { color: '#FF5533', accent: '#CC2200', tag: 'INTELLIGENCE ARTIFICIELLE' },
  'Cybersécurité':                          { color: '#0088FF', accent: '#0044BB', tag: 'CYBERSÉCURITÉ' },
  'Audit Digital Gratuit':                  { color: '#00BB55', accent: '#007733', tag: 'AUDIT DIGITAL' },
  'Pack SCALE - Excellence Opérationnelle': { color: '#FFCC00', accent: '#CC9900', tag: 'PACK SCALE' }
};

const service = draft.service || 'Service IKSATECH';
const meta    = serviceMap[service] || { color: '#0088FF', accent: '#0044BB', tag: service.toUpperCase().substring(0, 28) };

const fullText  = draft.linkedin_draft || '';
const sentences = fullText.split(/[.\n]/).map(s => s.trim()).filter(s => s.length > 15);
const desc      = (sentences[0] || service).substring(0, 88);

const liBgUrl = liUpload.secure_url;
const igBgUrl = igUpload.secure_url;

function buildPremiumHTML(bgUrl, width, height) {
  const cardBottom  = height > width ? 60 : 44;
  const cardPadH    = 44;
  const descSize    = height > width ? '18px' : '17px';

  return `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');
  * { margin:0; padding:0; box-sizing:border-box; }

  body {
    width: ${width}px;
    height: ${height}px;
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    position: relative;
    overflow: hidden;
    background: #050912;
  }

  /* ── BACKGROUND IMAGE ── */
  .bg {
    position: absolute;
    inset: 0;
    background-image: url('${bgUrl}');
    background-size: cover;
    background-position: center top;
    z-index: 0;
  }
  .bg::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse at 50% 0%, transparent 40%, rgba(5,9,18,0.30) 100%),
      radial-gradient(ellipse at 0% 50%, rgba(5,9,18,0.20) 0%, transparent 60%),
      radial-gradient(ellipse at 100% 50%, rgba(5,9,18,0.20) 0%, transparent 60%);
  }
  .bg::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 64%;
    background: linear-gradient(
      to top,
      rgba(5,9,18,0.97) 0%,
      rgba(5,9,18,0.90) 18%,
      rgba(5,9,18,0.68) 42%,
      rgba(5,9,18,0.12) 70%,
      transparent 100%
    );
  }

  /* ── TOP-RIGHT CORNER ACCENT ── */
  .corner-tl {
    position: absolute;
    top: 28px; right: 28px;
    z-index: 5;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
  }
  .corner-line-h {
    width: 72px; height: 1.5px;
    background: linear-gradient(90deg, transparent, ${meta.color}CC);
  }
  .corner-line-v {
    width: 1.5px; height: 56px;
    margin-right: 0;
    background: linear-gradient(180deg, ${meta.color}CC, transparent);
    align-self: flex-end;
  }
  .corner-dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: ${meta.color};
    box-shadow: 0 0 10px ${meta.color};
    align-self: flex-end;
  }

  /* ── PARTNER TAGLINE (top right) ── */
  .top-partner {
    position: absolute;
    top: 34px; right: 112px;
    z-index: 5;
    text-align: right;
    border-right: 2px solid ${meta.color}88;
    padding-right: 14px;
  }
  .top-partner .tp1 {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.18em;
    color: rgba(255,255,255,0.42);
    text-transform: uppercase;
  }
  .top-partner .tp2 {
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.12em;
    color: ${meta.color};
    text-transform: uppercase;
    margin-top: 3px;
  }

  /* ── MAIN GLASS CARD ── */
  .card {
    position: absolute;
    bottom: ${cardBottom}px;
    left: ${cardPadH}px;
    right: ${cardPadH}px;
    z-index: 10;
    background: linear-gradient(
      135deg,
      rgba(255,255,255,0.14) 0%,
      rgba(255,255,255,0.06) 50%,
      rgba(8,16,42,0.60) 100%
    );
    backdrop-filter: blur(28px);
    -webkit-backdrop-filter: blur(28px);
    border: 1px solid rgba(255,255,255,0.16);
    border-top: 1px solid rgba(255,255,255,0.28);
    border-left: 1px solid rgba(255,255,255,0.20);
    border-radius: 22px;
    padding: 28px 36px 30px;
    box-shadow:
      0 20px 80px rgba(0,0,0,0.75),
      0 4px 24px rgba(0,0,0,0.55),
      inset 0 1px 0 rgba(255,255,255,0.22),
      inset 0 -1px 0 rgba(0,0,0,0.18),
      0 0 100px ${meta.color}14;
    overflow: hidden;
  }
  /* Glow orb inside card */
  .card::before {
    content: '';
    position: absolute;
    top: -70px; left: -50px;
    width: 240px; height: 240px;
    background: radial-gradient(circle, ${meta.color}28 0%, transparent 65%);
    pointer-events: none;
    z-index: 0;
  }
  /* Shimmer line at top of card */
  .card::after {
    content: '';
    position: absolute;
    top: 0; left: 8%; right: 8%;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.42), transparent);
  }

  .card-inner { position: relative; z-index: 1; }

  /* ── TOP ROW: real logo + partner badge ── */
  .top-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 18px;
  }

  /* Real logo image from Cloudinary */
  .logo-img {
    height: 38px;
    width: auto;
    max-width: 220px;
    object-fit: contain;
    filter:
      drop-shadow(0 0 8px rgba(255,200,0,0.55))
      drop-shadow(0 0 18px rgba(255,160,0,0.30))
      brightness(1.08)
      contrast(1.05);
    /* Metallic gold tint on white/transparent logo */
    /* If logo is already gold this is a subtle enhancement */
  }

  /* Sub-label under logo */
  .logo-sub {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.24em;
    color: rgba(255,255,255,0.42);
    text-transform: uppercase;
    margin-top: 5px;
  }

  /* Partner tag right side */
  .partner-tag {
    text-align: right;
    border-left: 2px solid ${meta.color}77;
    padding-left: 14px;
  }
  .pt1 { font-size: 9px; font-weight: 700; letter-spacing: 0.18em; color: rgba(255,255,255,0.42); text-transform: uppercase; }
  .pt2 { font-size: 11px; font-weight: 800; letter-spacing: 0.10em; color: ${meta.color}; text-transform: uppercase; margin-top: 2px; }

  /* ── SERVICE BADGE ── */
  .service-badge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 15px;
  }
  .badge-line {
    width: 28px; height: 2px;
    background: linear-gradient(90deg, ${meta.color}, ${meta.color}44);
    border-radius: 2px;
    box-shadow: 0 0 8px ${meta.color}88;
  }
  .badge-label {
    font-size: 10.5px;
    font-weight: 800;
    letter-spacing: 0.20em;
    color: ${meta.color};
    text-transform: uppercase;
  }

  /* ── DESCRIPTION ── */
  .desc {
    font-size: ${descSize};
    font-weight: 500;
    line-height: 1.55;
    color: rgba(255,255,255,0.88);
    margin-bottom: 20px;
    text-shadow: 0 1px 6px rgba(0,0,0,0.55);
  }

  /* ── SEPARATOR ── */
  .sep {
    height: 1px;
    background: linear-gradient(90deg, rgba(255,255,255,0.20), ${meta.color}44, rgba(255,255,255,0.05));
    margin-bottom: 18px;
  }

  /* ── BOTTOM ROW ── */
  .bottom-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .website-block { display: flex; align-items: center; gap: 9px; }
  .web-dot {
    width: 6px; height: 6px;
    background: ${meta.color};
    border-radius: 50%;
    box-shadow: 0 0 8px ${meta.color}, 0 0 16px ${meta.color}66;
  }
  .website {
    font-size: 12px;
    font-weight: 700;
    color: rgba(255,255,255,0.62);
    letter-spacing: 0.07em;
  }
  .cta-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: linear-gradient(135deg, ${meta.color}EE 0%, ${meta.accent}DD 100%);
    color: #fff;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    padding: 11px 22px;
    border-radius: 50px;
    box-shadow:
      0 6px 20px ${meta.color}55,
      0 2px 8px rgba(0,0,0,0.40),
      inset 0 1px 0 rgba(255,255,255,0.25);
  }
</style>
</head>
<body>

  <!-- Background AI image -->
  <div class="bg"></div>

  <!-- Corner accent lines -->
  <div class="corner-tl">
    <div class="corner-dot"></div>
    <div class="corner-line-v"></div>
    <div class="corner-line-h"></div>
  </div>

  <!-- Top-right partner tag -->
  <div class="top-partner">
    <div class="tp1">Votre partenaire</div>
    <div class="tp2">en digital</div>
  </div>

  <!-- Premium glass card -->
  <div class="card">
    <div class="card-inner">

      <!-- Top row: REAL Cloudinary logo + partner label -->
      <div class="top-row">
        <div>
          <img class="logo-img" src="${logoUrl}" alt="IKSATECH" crossorigin="anonymous" />
          <div class="logo-sub">Digital Excellence</div>
        </div>
        <div class="partner-tag">
          <div class="pt1">Expertise</div>
          <div class="pt2">Premium</div>
        </div>
      </div>

      <!-- Service badge -->
      <div class="service-badge">
        <div class="badge-line"></div>
        <div class="badge-label">${meta.tag}</div>
      </div>

      <!-- Description -->
      <div class="desc">${desc}</div>

      <!-- Separator -->
      <div class="sep"></div>

      <!-- Bottom: website + CTA -->
      <div class="bottom-row">
        <div class="website-block">
          <div class="web-dot"></div>
          <div class="website">www.iksatech.com</div>
        </div>
        <div class="cta-btn">
          <span>Découvrir</span>
          <span style="font-size:14px;font-weight:900;">&#8594;</span>
        </div>
      </div>

    </div>
  </div>

</body>
</html>`;
}

const liHtml    = buildPremiumHTML(liBgUrl, 1080, 1080);
const igHtml    = buildPremiumHTML(igBgUrl, 1080, 1350);
const storyHtml = buildPremiumHTML(igBgUrl, 1080, 1920);

return [{
  json: {
    li_html:    liHtml,
    ig_html:    igHtml,
    story_html: storyHtml,
    service:    draft.service,
    draft_id:   draft.draft_id
  }
}];

const liFinal  = $json;
const igUpload = $('☁️ Upload Instagram Composite (Cloudinary)').first().json;
const draft    = $('⚙️ Parse AI Response').first().json;

if (!liFinal.secure_url) throw new Error('LI final composite missing: ' + JSON.stringify(liFinal));
if (!igUpload.secure_url) throw new Error('IG composite upload missing: ' + JSON.stringify(igUpload));

const liComposite = liFinal.secure_url;
const igComposite = igUpload.secure_url;

// ── Force Telegram-safe public JPG URL via Cloudinary transformation ──
// Replaces /upload/ with /upload/f_jpg,q_auto:best,w_1080/ in the URL
// This guarantees: public access, JPG format, correct size, no auth required
const igCompositeTelegram = igComposite.replace(
  '/upload/',
  '/upload/f_jpg,q_auto:best,w_1080/'
);

return [{
  json: {
    draft_id:               draft.draft_id,
    draft_id_for_button:    draft.draft_id_for_button,
    Status:                 'Waiting Approval ⏳',
    service_draft:          draft.service_draft,
    service:                draft.service,
    linkedin_draft:         draft.linkedin_draft,
    instagram_draft:        draft.instagram_draft,
    linkedin:               draft.linkedin,
    instagram:              draft.instagram,
    image_prompt_linkedin:  draft.image_prompt_linkedin,
    image_prompt_instagram: draft.image_prompt_instagram,
    linkedin_image_url:     liComposite,
    // instagram_image_url already set above with Telegram-safe URL
    instagram_story_url:    igComposite,
    li_base_url:            liComposite,
    ig_base_url:            igComposite,
    overlay_url:            igCompositeTelegram,
    instagram_image_url:    igCompositeTelegram,
    instagram_image_url_raw: igComposite
  }
}];

