const update = $input.first().json;
const callbackData = update?.callback_query?.data || '';
const colonIdx = callbackData.indexOf(':');
const action = colonIdx > -1 ? callbackData.substring(0, colonIdx) : callbackData;
const draft_id = colonIdx > -1 ? callbackData.substring(colonIdx + 1).trim() : '';
const callbackQueryId = update?.callback_query?.id || '';
const chatId = update?.callback_query?.message?.chat?.id || '5409067563';
return [{ json: { action: action.toUpperCase().trim(), draft_id, callbackQueryId, chatId } }];

